Ltac ifF_s := lazymatch goal with |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
  replace c with false; [cbv iota| symmetry; unfold_cond; rewrite ?signed_lit64 by lia; rewrite ?unsigned_lit by lia;
                                   solve_cond_rec] end.

